'use client'
import { useMediaQuery } from '@gentleduck/hooks/use-media-query'
import type React from 'react'
import {
  Drawer,
  DrawerClose,
  DrawerContent,
  DrawerDescription,
  DrawerFooter,
  DrawerHeader,
  DrawerTitle,
  DrawerTrigger,
} from '../drawer'
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from './dialog'

function DialogResponsive({ children, ...props }: React.ComponentPropsWithoutRef<typeof Dialog>): React.JSX.Element {
  const isDesktop = useMediaQuery('(min-width: 768px)')

  if (isDesktop) {
    return <Dialog {...props}>{children}</Dialog>
  }

  return <Drawer {...props}>{children}</Drawer>
}

function DialogTriggerResponsive({
  children,
  ...props
}: React.ComponentPropsWithoutRef<typeof DialogTrigger> &
  React.ComponentPropsWithoutRef<typeof DrawerTrigger>): React.JSX.Element {
  const isDesktop = useMediaQuery('(min-width: 768px)')

  if (isDesktop) {
    return <DialogTrigger {...props}>{children}</DialogTrigger>
  }

  return <DrawerTrigger {...props}>{children}</DrawerTrigger>
}

function DialogContentResponsive({
  children,
  ...props
}: React.ComponentPropsWithoutRef<typeof DialogContent>): React.JSX.Element {
  const isDesktop = useMediaQuery('(min-width: 768px)')

  if (isDesktop) {
    return (
      <DialogContent {...(props as React.ComponentPropsWithoutRef<typeof DialogContent>)}>{children}</DialogContent>
    )
  }

  return <DrawerContent {...(props as React.ComponentPropsWithoutRef<typeof DrawerContent>)}>{children}</DrawerContent>
}

function DialogHeaderResponsive({
  children,
  ...props
}: React.ComponentPropsWithoutRef<typeof DialogHeader>): React.JSX.Element {
  const isDesktop = useMediaQuery('(min-width: 768px)')

  if (isDesktop) {
    return <DialogHeader {...props}>{children}</DialogHeader>
  }

  return <DrawerHeader {...props}>{children}</DrawerHeader>
}

function DialogFooterResponsive({
  children,
  ...props
}: React.ComponentPropsWithoutRef<typeof DialogFooter>): React.JSX.Element {
  const isDesktop = useMediaQuery('(min-width: 768px)')

  if (isDesktop) {
    return <DialogFooter {...props}>{children}</DialogFooter>
  }

  return <DrawerFooter {...(props as {})}>{children}</DrawerFooter>
}

function DialogTitleResponsive({
  children,
  ...props
}: React.ComponentPropsWithoutRef<typeof DialogTitle>): React.JSX.Element {
  const isDesktop = useMediaQuery('(min-width: 768px)')

  if (isDesktop) {
    return <DialogTitle {...props}>{children}</DialogTitle>
  }

  return <DrawerTitle {...(props as {})}>{children}</DrawerTitle>
}

function DialogDescriptionResponsive({
  children,
  ...props
}: React.ComponentPropsWithoutRef<typeof DialogDescription>): React.JSX.Element {
  const isDesktop = useMediaQuery('(min-width: 768px)')

  if (isDesktop) {
    return <DialogDescription {...props}>{children}</DialogDescription>
  }

  return <DrawerDescription {...(props as {})}>{children}</DrawerDescription>
}

function DialogCloseResponsive({
  children,
  ...props
}: React.ComponentPropsWithoutRef<typeof DialogClose> &
  React.ComponentPropsWithoutRef<typeof DrawerClose>): React.JSX.Element {
  const isDesktop = useMediaQuery('(min-width: 768px)')

  if (isDesktop) {
    return <DialogClose {...props}>{children}</DialogClose>
  }

  return <DrawerClose {...props}>{children}</DrawerClose>
}

DialogResponsive.displayName = 'DialogResponsive'
DialogTriggerResponsive.displayName = 'DialogTriggerResponsive'
DialogContentResponsive.displayName = 'DialogContentResponsive'
DialogHeaderResponsive.displayName = 'DialogHeaderResponsive'
DialogFooterResponsive.displayName = 'DialogFooterResponsive'
DialogTitleResponsive.displayName = 'DialogTitleResponsive'
DialogDescriptionResponsive.displayName = 'DialogDescriptionResponsive'
DialogCloseResponsive.displayName = 'DialogCloseResponsive'

export {
  DialogCloseResponsive,
  DialogContentResponsive,
  DialogDescriptionResponsive,
  DialogFooterResponsive,
  DialogHeaderResponsive,
  DialogResponsive,
  DialogTitleResponsive,
  DialogTriggerResponsive,
}

'use client'

import { cn } from '@gentleduck/libs/cn'
import { loadDomAnimation } from '@gentleduck/motion/motion-features'
import { useMotionPreset } from '@gentleduck/motion/motion-presets'
import { springBouncy } from '@gentleduck/motion/transitions/springs'
import { MotionRootContext, useMotionContent, useMotionMount, useMotionRoot } from '@gentleduck/motion/use-motion-root'
import * as DialogPrimitive from '@gentleduck/primitives/dialog'
import { X } from 'lucide-react'
import { LazyMotion, m } from 'motion/react'
import * as React from 'react'

const Dialog = DialogPrimitive.Root
Dialog.displayName = 'Dialog'

const DialogTrigger = DialogPrimitive.Trigger
DialogTrigger.displayName = 'DialogTrigger'

const DialogPortal = DialogPrimitive.Portal
DialogPortal.displayName = 'DialogPortal'

const DialogClose = DialogPrimitive.Close
DialogClose.displayName = 'DialogClose'

const DialogOverlay = React.forwardRef<
  React.ComponentRef<typeof DialogPrimitive.Overlay>,
  React.ComponentPropsWithoutRef<typeof DialogPrimitive.Overlay>
>(({ className, ...props }, ref) => (
  <DialogPrimitive.Overlay
    ref={ref}
    className={cn(
      'data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 fixed inset-0 z-50 bg-black/80 data-[state=closed]:animate-out data-[state=open]:animate-in',
      'transition-all transition-discrete duration-[200ms,150ms] ease-(--duck-motion-ease)',
      className,
    )}
    {...props}
  />
))
DialogOverlay.displayName = DialogPrimitive.Overlay.displayName

const DialogContent = React.forwardRef<
  React.ComponentRef<typeof DialogPrimitive.Content>,
  React.ComponentPropsWithoutRef<typeof DialogPrimitive.Content> & { closeText?: string; hideClose?: boolean }
>(({ className, children, closeText = 'Close', hideClose = false, ...props }, ref) => (
  <DialogPortal>
    <DialogOverlay />
    <DialogPrimitive.Content
      ref={ref}
      className={cn(
        'data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 fixed top-1/2 left-1/2 z-50 grid w-full max-w-lg -translate-x-1/2 -translate-y-1/2 gap-4 border bg-background p-6 shadow-lg data-[state=closed]:animate-out data-[state=open]:animate-in sm:rounded-lg',
        'transition-all transition-discrete duration-[200ms,150ms] ease-(--duck-motion-ease)',
        className,
      )}
      {...props}>
      {children}
      {!hideClose && (
        <DialogPrimitive.Close className="absolute end-4 top-4 rounded-sm opacity-70 ring-offset-background transition-opacity hover:opacity-100 focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 disabled:pointer-events-none data-[state=open]:bg-accent data-[state=open]:text-muted-foreground">
          <X aria-hidden="true" className="h-4 w-4" />
          <span className="sr-only">{closeText}</span>
        </DialogPrimitive.Close>
      )}
    </DialogPrimitive.Content>
  </DialogPortal>
))
DialogContent.displayName = DialogPrimitive.Content.displayName

const DialogHeader = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(
  ({ className, ...props }, ref) => (
    <div ref={ref} className={cn('flex flex-col space-y-1.5 text-center sm:text-start', className)} {...props} />
  ),
)
DialogHeader.displayName = 'DialogHeader'

const DialogFooter = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(
  ({ className, ...props }, ref) => (
    <div ref={ref} className={cn('flex flex-col-reverse sm:flex-row sm:justify-end sm:gap-2', className)} {...props} />
  ),
)
DialogFooter.displayName = 'DialogFooter'

const DialogTitle = React.forwardRef<
  React.ComponentRef<typeof DialogPrimitive.Title>,
  React.ComponentPropsWithoutRef<typeof DialogPrimitive.Title>
>(({ className, ...props }, ref) => (
  <DialogPrimitive.Title
    ref={ref}
    className={cn('font-semibold text-lg leading-none tracking-tight', className)}
    {...props}
  />
))
DialogTitle.displayName = DialogPrimitive.Title.displayName

const DialogDescription = React.forwardRef<
  React.ComponentRef<typeof DialogPrimitive.Description>,
  React.ComponentPropsWithoutRef<typeof DialogPrimitive.Description>
>(({ className, ...props }, ref) => (
  <DialogPrimitive.Description ref={ref} className={cn('text-muted-foreground text-sm', className)} {...props} />
))
DialogDescription.displayName = DialogPrimitive.Description.displayName

/* ------------------------------------------------------------------ */
/*  MotionDialog + MotionDialogContent                                 */
/* ------------------------------------------------------------------ */

function MotionDialog({
  children,
  open,
  defaultOpen,
  onOpenChange,
  ...rest
}: React.ComponentPropsWithoutRef<typeof DialogPrimitive.Root>) {
  const { rootProps, contextValue } = useMotionRoot({ open, defaultOpen, onOpenChange })
  return (
    <MotionRootContext.Provider value={contextValue}>
      <DialogPrimitive.Root {...rootProps} {...rest}>
        {children}
      </DialogPrimitive.Root>
    </MotionRootContext.Provider>
  )
}
MotionDialog.displayName = 'MotionDialog'

const MotionDialogContent = React.forwardRef<
  React.ComponentRef<typeof DialogPrimitive.Content>,
  React.ComponentPropsWithoutRef<typeof DialogPrimitive.Content> & {
    closeText?: string
    hideClose?: boolean
  }
>(({ className, children, closeText = 'Close', hideClose = false, ...props }, ref) => {
  const { isOpen } = useMotionContent()
  const overlay = useMotionPreset('fadeIn', { transition: springBouncy })
  const content = useMotionPreset('scaleIn', { transition: springBouncy })
  const shouldRender = useMotionMount(isOpen)

  if (!shouldRender) return null

  return (
    <LazyMotion features={loadDomAnimation}>
      <DialogPortal forceMount>
        <DialogPrimitive.Overlay forceMount asChild>
          <m.div
            className="fixed inset-0 z-50 bg-black/80"
            initial={overlay.initial}
            animate={isOpen ? overlay.animate : { ...overlay.exit, pointerEvents: 'none' }}
            transition={overlay.transition}
          />
        </DialogPrimitive.Overlay>
        <DialogPrimitive.Content ref={ref} forceMount asChild {...props}>
          <m.div
            className={cn(
              'fixed top-1/2 left-1/2 z-50 grid w-full max-w-lg -translate-x-1/2 -translate-y-1/2 gap-4 border bg-background p-6 shadow-lg sm:rounded-lg',
              className,
            )}
            initial={content.initial}
            animate={isOpen ? content.animate : { ...content.exit, pointerEvents: 'none' }}
            transition={content.transition}>
            {children}
            {!hideClose && (
              <DialogPrimitive.Close className="absolute end-4 top-4 rounded-sm opacity-70 ring-offset-background transition-opacity hover:opacity-100 focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 disabled:pointer-events-none data-[state=open]:bg-accent data-[state=open]:text-muted-foreground">
                <X aria-hidden="true" className="h-4 w-4" />
                <span className="sr-only">{closeText}</span>
              </DialogPrimitive.Close>
            )}
          </m.div>
        </DialogPrimitive.Content>
      </DialogPortal>
    </LazyMotion>
  )
})
MotionDialogContent.displayName = 'MotionDialogContent'

export {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogOverlay,
  DialogPortal,
  DialogTitle,
  DialogTrigger,
  MotionDialog,
  MotionDialogContent,
}
